// ─────────────────────────────────────────────────────────────
// NODO FUNCTION: Generar datos de bicicletas (Mapeo Exacto 5x5)
// ─────────────────────────────────────────────────────────────

const registryDates = [
    '2025-11-20T00:00:00.000Z',
    '2025-09-05T00:00:00.000Z',
    '2025-05-14T00:00:00.000Z',
    '2024-12-01T00:00:00.000Z',
    '2024-07-18T00:00:00.000Z'
];

const kmByAge = [18, 95, 310, 620, 1140];
const batteries = [95, 82, 74, 61, 48];

// Estados personalizados por estación
// ST-01: Mixed (3 available, 1 in-use, 1 maintenance)
// ST-02: Mixed (3 available, 1 in-use, 1 maintenance)
// ST-03: Paseo Shopping - TODAS DISPONIBLES
// ST-04: Mixed (3 available, 1 in-use, 1 maintenance)
// ST-05: UTMACH - TODAS OCUPADAS (in-use)
const statusesByStation = {
    '1': ['available', 'available', 'available', 'in-use', 'maintenance'],      // ST-01: Normal
    '2': ['available', 'available', 'available', 'in-use', 'maintenance'],      // ST-02: Normal
    '3': ['available', 'available', 'available', 'available', 'available'],     // ST-03: Paseo - TODAS DISPONIBLES
    '4': ['available', 'available', 'available', 'in-use', 'maintenance'],      // ST-04: Normal
    '5': ['in-use', 'in-use', 'in-use', 'in-use', 'in-use']                   // ST-05: UTMACH - TODAS OCUPADAS
};

function generateBikes(stationPrefix, stationId, baseLat, baseLng, customStatuses) {
    const statuses = customStatuses || ['available', 'available', 'available', 'in-use', 'maintenance'];

    return Array.from({ length: 5 }, (_, i) => ({
        id: `B-${stationPrefix}${String(i + 1).padStart(2, '0')}`,
        stationId: stationId,
        dockNumber: i + 1,
        status: statuses[i],
        location: {
            lat: +(baseLat + i * 0.00015).toFixed(6),
            lng: +(baseLng + i * 0.00012).toFixed(6)
        },
        battery: batteries[i],
        registeredAt: registryDates[i],
        totalKmRidden: kmByAge[i]
    }));
}

// Cada una de las 5 estaciones cuenta con un andén rígido de exactamente 5 puertos
const stationDefs = [
    {
        id: 'ST-01',
        name: 'Estación Escuela UNE - ECU 911',
        location: { lat: -3.2548668270081267, lng: -79.9743581107955 },
        address: 'Av. Arízaga y Av. Alejandro Castro Benítez, Machala',
        totalPorts: 5,
        prefix: '1'
    },
    {
        id: 'ST-02',
        name: 'Estación Parque Central',
        location: { lat: -3.2588242448575415, lng: -79.9595325493993 },
        address: 'Av. 25 de Junio y Rocafuerte, Machala',
        totalPorts: 5,
        prefix: '2'
    },
    {
        id: 'ST-03',
        name: 'Estación Paseo Shopping',
        location: { lat: -3.2804318462424735, lng: -79.93216057112552 },
        address: 'Av. 25 de Junio (Frente al Paseo Shopping), Machala',
        totalPorts: 5,
        prefix: '3'
    },
    {
        id: 'ST-04',
        name: 'Estación Terminal Terrestre',
        location: { lat: -3.279880008293559, lng: -79.91541014356491 },
        address: 'Av. Ferroviaria y Vía de Evitamiento, Machala',
        totalPorts: 5,
        prefix: '4'
    },
    {
        id: 'ST-05',
        name: 'Estación UTMACH (Universidad)',
        location: { lat: -3.2860729779327067, lng: -79.91225838067605 },
        address: 'Av. Panamericana (Campus Principal UTMACH), Machala',
        totalPorts: 5,
        prefix: '5'
    }
];

const stations = stationDefs.map(def => {
    // Obtener los estados personalizados para esta estación
    const customStatuses = statusesByStation[def.prefix];
    const bikes = generateBikes(def.prefix, def.id, def.location.lat, def.location.lng, customStatuses);

    // 1. Bicicletas listas para ser rentadas (status === 'available')
    const availableBikes = bikes.filter(b => b.status === 'available').length;

    // 2. Bicicletas físicamente en el andén ocupando espacio (Disponibles + Mantenimiento)
    // Las 'in-use' no están en la estación, por lo que dejan el puerto vacío.
    const dockedBikes = bikes.filter(b => b.status !== 'in-use').length;

    // 3. Puertos vacíos = Capacidad total (5) - Bicicletas ancladas físicamente
    const emptyPorts = def.totalPorts - dockedBikes;

    return {
        id: def.id,
        name: def.name,
        address: def.address,
        location: def.location,

        availableBikes,                     // Bicis que el usuario verá en la grilla para llevarse
        totalBikes: def.totalPorts,         // Capacidad máxima física estricta (5)
        emptyPorts,                         // Espacios libres reales en el hierro para enganchar otra bici
        totalPorts: def.totalPorts,

        bikes
    };
});

const bikeData = {
    timestamp: new Date().toISOString(),
    stations,
    bikes: stations.flatMap(s => s.bikes), // Las 25 bicicletas indexadas linealmente
    analytics: {
        totalTrips: 3824,
        activeUsers: 1247,
        avgTripDuration: '23 min',
        peakHour: '18:00',
        totalDistance: '4,827 km'
    }
};

msg.payload = bikeData;
return msg;

// Convertir a JSON para enviar por WebSocket
msg.payload = JSON.stringify(msg.payload);
return msg;

// Análisis por hora y rutas
const now = new Date();
const hourlyData = [];
const routeData = {};

for (let i = 0; i < 24; i++) {
  hourlyData.push({
    hour: i + ':00',
    trips: Math.floor(Math.random() * 300) + 50,
    activeUsers: Math.floor(Math.random() * 200) + 30,
    avgDistance: (Math.random() * 15 + 5).toFixed(2)
  });
}

const routes = [
  { name: 'Centro → Parque', trips: 324, distance: '1.2 km', duration: '8 min' },
  { name: 'Terminal → Universidad', trips: 287, distance: '2.5 km', duration: '15 min' },
  { name: 'Zona Comercial → Hospital', trips: 256, distance: '1.8 km', duration: '11 min' },
  { name: 'Centro → Hospital', trips: 198, distance: '3.1 km', duration: '19 min' },
  { name: 'Parque → Universidad', trips: 176, distance: '2.0 km', duration: '12 min' }
];

msg.payload = {
  timestamp: now.toISOString(),
  hourlyUsage: hourlyData,
  topRoutes: routes,
  dailySummary: {
    totalTrips: 3824,
    totalDistance: 4827,
    averageTrip: 1.26,
    co2Saved: '1,245 kg'
  },
  weeklySummary: {
    totalTrips: 24568,
    totalDistance: 31450,
    averageTrip: 1.28,
    co2Saved: '8,067 kg'
  }
};

return msg;

const origin = "2.1898,-79.8857"; 
const destination = "2.1910,-79.8845";
const apiKey = "AIzaSyDDxxIvsgpbYfdGXO8t-md7aQ5Sh6-mtqk";

axios.get(`https://maps.googleapis.com/maps/api/directions/json`, {
  params: {
    origin: origin,
    destination: destination,
    key: apiKey
  }
})
.then(response => {
  // Verificamos que la API haya devuelto datos válidos antes de mapear
  if (response.data.routes && response.data.routes.length > 0) {
    msg.payload.mapsData = {
      distance: response.data.routes[0].legs[0].distance.text,
      duration: response.data.routes[0].legs[0].duration.text,
      polyline: response.data.routes[0].overview_polyline.points
    };
  }
  // Enviamos el mensaje de forma asíncrona al siguiente nodo (OpenWeather)
  node.send(msg); 
})
.catch(error => {
  node.error("Error en Google Maps API: " + error.message, msg);
  // Enviamos el msg original de todas formas para no romper el flujo de la flota
  node.send(msg); 
});

// Importante: No retornar nada al final de la función para evitar duplicados manuales
return;

const lat = -3.2584011156988226; 
const lon = -79.95965704657748;
const apiKey = 'db12dfb0d8b713952329193b79cd808a';

axios.get(`https://api.openweathermap.org/data/2.5/weather`, {
  params: {
    lat: lat,
    lon: lon,
    appid: apiKey,
    units: 'metric'
  }
})
  .then(response => {
    // Conservamos lo que traía msg.payload y le agregamos la propiedad climática
    msg.payload.weatherData = {
      temperature: response.data.main.temp,
      condition: response.data.weather[0].main,
      humidity: response.data.main.humidity,
      windSpeed: response.data.wind.speed
    };
    node.send(msg);
  })
  .catch(error => {
    node.error("Error en OpenWeather API: " + error.message, msg);
    node.send(msg);
  });

return;
